#!/usr/bin/env node
// Manages the local `.env` across environment tiers (dev/test/sit/uat/staging/prod).
//
// Storage: .env.sample documents every key with a `# scope:shared|tier|personal|auto`
// comment on its own line above the key. Real values live in gitignored
// .env.shared (same across all tiers) and .env.<tier> (differs per tier) —
// never committed.
//
// Usage:
//   node scripts/switchEnv.mjs                — report the currently active tier
//   node scripts/switchEnv.mjs init            — scaffold .env.shared + every
//                                                 .env.<tier> at once (skips files
//                                                 that already exist), so a dev can
//                                                 fill in all tokens in one pass
//                                                 instead of tier by tier
//   node scripts/switchEnv.mjs validate [--live] — check every existing .env.shared /
//                                                 .env.<tier> file against
//                                                 .env.sample's schema, plus
//                                                 cross-checks (OCAPI host vs
//                                                 config/<tier>.js, Contentful
//                                                 environment id vs tier). With
//                                                 --live, also makes a real
//                                                 read-only Contentful Delivery
//                                                 API call AND a real SLAS guest
//                                                 (client_credentials) token
//                                                 request per tier, confirming
//                                                 the credentials actually work
//                                                 — not just that they're set
//   node scripts/switchEnv.mjs <tier>          — switch to <tier>, merging
//                                                 .env.shared + .env.<tier> into
//                                                 .env (tier values win on
//                                                 collision) and stamping
//                                                 ENVIRONMENT_NAME + DEPLOY_TARGET
//
// `init` also auto-fetches CONTENTFUL_ENVIRONMENT_ID, CONTENTFUL_DELIVERY_TOKEN,
// and CONTENTFUL_PREVIEW_TOKEN for every tier once .env.shared has a
// CONTENTFUL_MANAGEMENT_TOKEN + CONTENTFUL_SPACE_ID — reusing the same Content
// Management API read (client.apiKey.getMany / client.previewApiKey.get) and
// the same @ZimmermannAU/tier-1-approvers write gate as `npm run
// config:contentful` (scripts/contentful/setup/getConfig.mjs). The environment
// id comes from the same call — an API key's `environments` link only ever
// points at a real environment, so finding a token for a tier also confirms
// that tier's environment exists. It only reads existing API keys/environments
// — it never creates new ones in Contentful.
//
// SFCC values (org id, short code, OCAPI host, SLAS client id/secret) are NOT
// auto-fetched: there's no discovery API (you need the short code to call any
// SFCC API in the first place), and OAuth client secrets are never retrievable
// after creation. See .docs/integration/01-sfcc.md — these remain manual entry.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execSync } from 'node:child_process';
import { createClient as createContentfulClient } from './contentful/setup/_shared.mjs';

const ROOT = process.cwd();
const TIERS = ['dev', 'test', 'sit', 'uat', 'staging', 'prod'];
// DEPLOY_TARGET picks config/{target}.js in pwa-kit-runtime's getConfig(), and also
// names the config file on disk for the cross-checks below. `prod` is the only tier
// where the local slug and the file/MRT target name diverge — see
// config/production.js and the `push:prod -t production` npm script.
const DEPLOY_TARGET_MAP = {
  dev: 'dev',
  test: 'test',
  sit: 'sit',
  uat: 'uat',
  staging: 'staging',
  prod: 'production',
};
// Confirmed environment strategy (2026-07-11): single Contentful space, per-tier
// environment id. `prod` is the only tier that doesn't just reuse its own slug.
const CONTENTFUL_ENV_MAP = {
  dev: 'dev',
  test: 'test',
  sit: 'sit',
  uat: 'uat',
  staging: 'staging',
  prod: 'master',
};
// `validate --live` runs sequentially across all 6 tiers for both checks — a single
// stalled sandbox must fail fast rather than hang the whole command.
const LIVE_CHECK_TIMEOUT_MS = 10_000;

function readEnvFile(filePath) {
  if (!fs.existsSync(filePath)) return null;
  const entries = [];
  for (const raw of fs.readFileSync(filePath, 'utf8').split('\n')) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) continue;
    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;
    entries.push([line.slice(0, eqIdx).trim(), line.slice(eqIdx + 1).trim()]);
  }
  return entries;
}

// Section headers look like `# ── Commerce / SFCC ───────────────`.
const SECTION_HEADER_RE = /^#\s*──+\s*(.+?)\s*──+\s*$/;
